        'lojas-e-comercio' => ['name' => 'Shops and retail', 'title' => 'Online Store and Digital Catalog for Local Shops', 'description' => 'Online store with card, Apple Pay and Google Pay, a catalog with ordering by message and a Google profile for clothing, gift, beauty and local shops.', 'h1' => 'Sell to people who never walk past your door', 'pains' => ['Selling only to people who walk by', 'Answering price questions one DM at a time', 'Losing sales after hours'], 'services' => ['loja-virtual', 'cardapio-digital', 'google-meu-negocio', 'atendimento-whatsapp'], 'intro' => 'Your products can sell 24 hours a day. An online store or a catalog with ordering by message puts your shop window on every phone in town.'],
        'prestadores-de-servico' => ['name' => 'Service providers', 'title' => 'Website Design for Service Businesses and Contractors', 'description' => 'Website, landing page and Google profile for lawyers, accountants, architects, personal trainers, electricians, cleaners and other service businesses.', 'h1' => 'More quote requests, less time explaining', 'pains' => ['Relying only on referrals', 'Explaining the same thing to every customer', 'Not looking as trustworthy as you are'], 'services' => ['landing-page', 'site-profissional', 'google-meu-negocio', 'atendimento-whatsapp'], 'intro' => 'Referrals are great, but they do not pay the bills every month. A well-built website and a strong Google profile bring in customers who do not know you yet and arrive already trusting you.'],
        'cafeterias-e-padarias' => ['name' => 'Cafes and bakeries', 'title' => 'Digital Menu for Cafes and Bakeries | QR Code Ordering', 'description' => 'QR code digital menu with direct ordering by message and no commission, plus a Google Maps profile for cafes, bakeries and dessert shops.', 'h1' => 'Your menu on the counter and on the phone, with the order ready in your chat', 'pains' => ['Counter and delivery orders written down by hand', 'A paper menu that is out of date every time a price changes', 'Passers-by cannot find your cafe on Google Maps'], 'services' => ['cardapio-digital', 'google-meu-negocio', 'cartao-digital', 'atendimento-whatsapp'], 'intro' => 'A good cafe lives on regulars and on new people discovering the place. A digital menu that is always up to date, with the order arriving ready in your chat, plus a strong Google Maps profile, brings both, with no commission per order.', 'who' => 'a cafe or bakery', 'faq' => [
            ['How much does a digital menu for a cafe cost?', 'US$ 249, one-time payment, ready in about 3 days, with no commission per order.'],
            ['How do customers open the menu at the counter?', 'A QR code comes ready to print. Customers point their phone at it and the menu opens in the browser, with no app to download.'],
            ['Can I set a delivery fee by neighborhood?', 'Yes. Opening hours and a delivery fee by neighborhood are part of the menu.'],
        ]],
