        'estudios-e-academias' => ['name' => 'Pilates, yoga and personal training studios', 'title' => 'Online Booking for Pilates, Yoga and Fitness Studios', 'description' => 'Online class booking with WhatsApp reminders, a website and a Google profile for pilates, yoga and functional training studios and personal trainers.', 'h1' => 'Classes booked on their own, clients reminded, fewer no-shows', 'pains' => ['Clients booking and cancelling classes by message', 'No-shows that leave a slot empty', 'New clients who cannot find your plans and schedule'], 'services' => ['agendamento-online', 'site-profissional', 'google-meu-negocio', 'cartao-digital'], 'intro' => 'Teachers should not spend the day on their phone sorting out schedules. With online booking, clients pick a time, get a reminder and you just check your schedule. A website and Google profile show your plans and location and let new clients reach you in one tap.', 'who' => 'a studio', 'faq' => [
